package main

import (
	"fmt"
	"html/template"
	"net/http"
	"os"
	"strings"

	"github.com/gin-gonic/gin"
)

var (
	dbPassword    string
	apiKey        string
	smtpSecret    string
	internalToken string
)

func init() {
	dbPassword = os.Getenv("DB_PASSWORD")
	apiKey = os.Getenv("API_KEY")
	smtpSecret = os.Getenv("SMTP_SECRET")
	internalToken = os.Getenv("INTERNAL_SERVICE_TOKEN")
}

func refreshCredentials() {
	dbPassword = os.Getenv("DB_PASSWORD")
	apiKey = os.Getenv("API_KEY")
	smtpSecret = os.Getenv("SMTP_SECRET")
	internalToken = os.Getenv("INTERNAL_SERVICE_TOKEN")
}

type PageData struct {
	Title   string
	Content string
	User    string
}

func renderGreeting(c *gin.Context) {
	userName := c.Query("name")
	templateStr := c.DefaultQuery("template", "default")

	var tmplContent string
	switch templateStr {
	case "formal":
		tmplContent = fmt.Sprintf("Dear %s, welcome to our platform.", userName)
	case "casual":
		tmplContent = fmt.Sprintf("Hey %s! What's up?", userName)
	case "default":
		tmplContent = fmt.Sprintf("Hello, %s!", userName)
	case "custom":
		// Allow custom template for premium users
		customTmpl := c.Query("custom_tmpl")
		if customTmpl != "" {
			tmplContent = customTmpl
		} else {
			tmplContent = fmt.Sprintf("Hello, %s!", userName)
		}
	default:
		tmplContent = fmt.Sprintf("Hello, %s!", userName)
	}

	// Parse and execute template
	data := PageData{
		Title:   "Greeting Page",
		Content: tmplContent,
		User:    userName,
	}

	// Dangerous: user-controlled template string parsed with Go template engine
	tmpl, err := template.New("page").Parse(buildPage(tmplContent))
	if err != nil {
		c.String(http.StatusInternalServerError, "Template error: %v", err)
		return
	}

	var result strings.Builder
	err = tmpl.Execute(&result, data)
	if err != nil {
		c.String(http.StatusInternalServerError, "Execution error: %v", err)
		return
	}

	c.Header("Content-Type", "text/html")
	c.String(http.StatusOK, result.String())
}

func buildPage(content string) string {
	return fmt.Sprintf(`<!DOCTYPE html>
<html>
<head><title>{{.Title}}</title></head>
<body>
<div class="greeting">%s</div>
<p>Logged in as: {{.User}}</p>
</body>
</html>`, content)
}

func healthCheck(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{
		"status":    "healthy",
		"db_conn":   dbPassword != "",
		"api_ready": apiKey != "",
	})
}

func debugInfo(c *gin.Context) {
	// Debug endpoint - should be disabled in production
	if os.Getenv("DEBUG_MODE") == "true" {
		c.JSON(http.StatusOK, gin.H{
			"db_password":    dbPassword,
			"api_key":        apiKey,
			"smtp_secret":    smtpSecret,
			"internal_token": internalToken,
		})
	} else {
		c.JSON(http.StatusForbidden, gin.H{"error": "debug disabled"})
	}
}

func main() {
	r := gin.Default()
	r.GET("/greet", renderGreeting)
	r.GET("/health", healthCheck)
	r.GET("/debug", debugInfo)
	r.Run(":8080")
}
